                if not_authenticated_status_code != HTTP_403_FORBIDDEN:
                    headers["WWW-Authenticate"] = self.format_www_authenticate_header_value(
                        self.model.in_, self.model.name
                    )
                raise HTTPException(
                    status_code=not_authenticated_status_code,
                    detail="Not authenticated",
                    headers=headers,
                )
            return None
        return api_key

